"""Build generic static worked cases; --check compares every generated byte.

Edit CASES or SIZES to extend the demonstration, then regenerate. The YAMLs
are generated inputs, not an independent design database. Only the existing
open-source screen is executed; no production solver modules are modified.

Independent stress derivation: a longitudinal cut balances differential
pressure against two walls, giving hoop = (pi-pe)*OD/(2*t). Closed-end
pressure thrust is Fp = pi_math/4*(pi*ID**2-pe*OD**2); steel area is
A = pi_math/4*(OD**2-ID**2). Axial membrane stress is (T+Fp)/A.
Elastic outer-fibre bending adds both signs of E*OD*kappa/2. Plane-stress
von Mises is sqrt(axial**2+hoop**2-axial*hoop); utilisation divides by yield.
Cable equilibrium dV/ds = -w and tan(theta) = V/H, with theta the tangent
angle from horizontal (not the input hang-off angle from vertical), give curvature
abs(w)*H/T**2. Thus hang-off uses (Ttop, w*H/Ttop**2), touchdown and
sag use (H, w/H), and hog uses (H, abs(w*(1-factor))/H). Both axial signs
are checked at each named section; the largest utilisation governs, with
the first named section retained on an exact tie. No sampled shape point
or stress helper is used by this independent comparator.
"""

import json
import math
from pathlib import Path
import sys

import yaml

ROOT = Path(__file__).resolve().parents[2]
HERE = Path(__file__).resolve().parent
INPUTS = Path("examples/workflows/riser-worked-configurations")
OUTPUT = Path("docs/domains/risers/worked-configurations")
CASES = [("SCR", 1000, 8), ("SCR", 1500, 10), ("SCR", 2000, 12),
         ("SLWR", 1500, 8), ("SLWR", 2000, 10), ("SLWR", 2500, 12)]
SIZES = {8: (.219075, [.015875, .018263, .022225]),
         10: (.273050, [.018263, .021438, .025400]),
         12: (.323850, [.021438, .025400, .028575])}
MODEL_SOURCE = "src/digitalmodel/subsea/catenary_riser/models.py"
STRESS_RELATIVE_TOLERANCE = 1e-6
BASES = {
    "top_tension_n": "assumed: 0.6 * specified minimum yield strength * steel area",
    "bend_radius_m": "assumed screening strain limit 0.2%; OD/(2*0.002), not a code value",
    "hog_clearance_m": "assumed minimum hog clearance of 50.0 m",
    "static_von_mises_utilisation": "an assumed screening ratio of 0.67 (two thirds rounded to two decimals) on von Mises stress; a project shall replace it with the governing code design factor",
    "shape_closure": "numerical closure tolerance from riser_configuration_screen/static.py::CLOSURE_M",
    "net_buoyancy": "screen domain: buoyancy_factor > 1 for a net-buoyant section",
    "hog_above_sag": "screen domain: hog_fraction > sag_fraction",
}


# Comparator section: these functions use only math and supplied scalars.
# No screen or catenary imports are used here; stress uses exposed H and Ttop.
def scr_comparator(weight, depth, angle_deg):
    """Closed-form inextensible catenary, horizontal tangent at touchdown."""
    sine = math.sin(math.radians(angle_deg))
    horizontal = weight * depth * sine / (1 - sine)
    radius = horizontal / weight
    length = math.sqrt(depth**2 + 2 * radius * depth)
    return {"horizontal_tension_n": horizontal, "top_tension_n": horizontal + weight * depth,
            "suspended_length_m": length, "horizontal_span_m": radius * math.asinh(length / radius),
            "touchdown_radius_m": radius}


def slwr_comparator(weight, factor, horizontal, start, buoyed, suspended):
    """Global vertical balance; no grounded bare tail contributes to V_top."""
    end_bare = suspended - start - buoyed
    if min(start, buoyed, end_bare) < 0:
        raise ValueError("negative suspended segment length")
    vertical = math.fsum([weight * start, weight * (1-factor) * buoyed, weight * end_bare])
    return {"top_tension_n": math.hypot(horizontal, vertical),
            "sag_radius_m": horizontal / weight,
            "hog_radius_m": horizontal / abs(weight * (1-factor))}


def stress_comparator(pipe, weight, horizontal, top, factor=None):
    """Evaluate exact named sections with math and supplied scalars only."""
    outer, wall = pipe["outer_diameter_m"], pipe["wall_thickness_m"]
    inner = outer - 2*wall
    area = math.pi * (outer**2 - inner**2) / 4
    inside, outside = pipe["internal_pressure_pa"], pipe["external_pressure_pa"]
    hoop = (inside - outside) * outer / (2*wall)
    pressure_force = math.pi / 4 * (inside*inner**2 - outside*outer**2)
    sections = [("hang-off", top, weight*horizontal/top**2),
                ("touchdown", horizontal, weight/horizontal)]
    if factor is not None:
        sections += [("sag bend", horizontal, weight/horizontal),
                     ("hog bend", horizontal, abs(weight*(1-factor))/horizontal)]
    values = {}
    for name, tension, curvature in sections:
        membrane = (tension + pressure_force) / area
        bending = pipe["youngs_modulus_pa"] * outer * curvature / 2
        values[name] = max(math.sqrt(axial**2 + hoop**2 - axial*hoop)
                           for axial in (membrane-bending, membrane+bending)) / pipe["yield_strength_pa"]
    governing = max(values, key=values.get)
    return {"comparator_value": values[governing], "governing_critical_section": governing,
            "critical_section_utilisations": values}


def stress_comparison(settings, configuration, row):
    """Compare sampled stress with exact named sections without tuning tolerance."""
    reference = stress_comparator(settings["pipe"], settings["submerged_weight_n_m"],
                                  row["horizontal_tension_n"], row["top_tension_n"],
                                  configuration.get("buoyancy_factor"))
    result = comparison(reference["comparator_value"], row["static_von_mises_utilisation"],
                        "independent thin-wall implementation and named critical sections, conditional on exposed H and Ttop")
    result.update(reference)
    result["relative_tolerance"] = STRESS_RELATIVE_TOLERANCE
    result["status"] = "pass" if abs(result["difference_percent"]) <= 100*STRESS_RELATIVE_TOLERANCE else "not established"
    result["missing_evidence"] = ("" if result["status"] == "pass" else
                                  "dense or continuous-section stress-envelope verification resolving sampled versus exact critical-section disagreement")
    return result


def comparison(reference, actual, scope):
    """Compare to an independent value at a relative tolerance of 1e-6."""
    difference = 100 * (actual - reference) / reference
    return {"comparator_value": reference, "screen_value": actual,
            "difference_percent": difference, "relative_tolerance": 1e-6,
            "status": "pass" if abs(difference) <= .0001 else "violation", "scope": scope}


def round_values(value):
    """Round float leaves to six significant figures without nonfinite JSON."""
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError("nonfinite generated value")
        return float(format(value, ".6g")) if value else 0.0
    if isinstance(value, dict):
        return {key: round_values(item) for key, item in value.items()}
    if isinstance(value, list):
        return [round_values(item) for item in value]
    return value


def settings_for(kind, depth, size, thickness):
    """Compute submerged weight and limits from the assumed pipe dimensions."""
    od = SIZES[size][0]
    bore = math.pi * (od - 2 * thickness)**2 / 4
    displaced = math.pi * od**2 / 4
    steel_area = displaced - bore
    content = 0.0 if size == 12 else 850.0
    weight = 9.80665 * (7850 * steel_area + content * bore - 1025 * displaced)
    axes = {"hangoff_angle_deg": [float(a) for a in range(8, 21, 2)]}
    if kind == "SLWR":
        axes = {"hangoff_angle_deg": [6., 8., 10., 12.], "buoyancy_factor": [1.5, 2., 2.5],
                "sag_fraction": [.1, .2, .3], "hog_fraction": [.25, .35, .5]}
    return {
        "riser_type": kind, "water_depth_m": float(depth), "submerged_weight_n_m": weight,
        "data_basis": "generic assumed values for a public worked configuration; no project data",
        "criteria_revision": "worked-config-1", "provisional": True,
        "grounded_length_m": .5 * depth,
        "offsets_m": [-.05 * depth, 0., .05 * depth, {"x_m": 0., "y_m": .05 * depth}],
        "weight_basis": {"steel_density_kg_m3": 7850., "content_density_kg_m3": content,
                         "seawater_density_kg_m3": 1025., "gravity_m_s2": 9.80665},
        "pipe": {"outer_diameter_m": od, "wall_thickness_m": thickness,
                 "youngs_modulus_pa": 207e9, "yield_strength_pa": 448e6,
                 "internal_pressure_pa": 20e6, "external_pressure_pa": 0.},
        "constraints": {"max_top_tension_n": .6 * 448e6 * steel_area,
                        "min_bend_radius_m": od / (2 * .002),
                        "min_hog_clearance_m": 50., "max_static_utilisation": .67},
        "axes": axes}


def input_yaml(case_id, settings):
    """Write the router schema with explicit assumed/cited basis comments."""
    pipe = settings["pipe"]
    nominal = pipe["outer_diameter_m"] / .0254
    header = (f"# Generic nominal {nominal:.3f} in OD, {pipe['wall_thickness_m']*1000:.3f} mm wall\n"
              "# chosen for demonstration (assumed), not a design or vendor catalogue.\n"
              f"# Steel E=207e9 Pa, density=7850 kg/m3, SMYS=448e6 Pa: {MODEL_SOURCE}\n"
              "# STEEL_API_5L_X65 (MPa converted to Pa); repository nominal API 5L X65 values.\n"
              "# Oil=850 kg/m3; empty=0 kg/m3 gas-lift proxy (assumed) for 12 in cases.\n"
              "# Seawater=1025 kg/m3; g=9.80665 m/s2 (assumed); uncoated pipe.\n"
              "# Grounded bare tail=50% water depth (assumed); near/far/cross=5% depth.\n"
              "# Internal design pressure=20.0e6 Pa at hang-off; external=0 Pa at surface hang-off.\n"
              "# Limitation: screen applies this single hang-off pressure pair to the whole line.\n")
    document = {"basename": "riser_configuration_screen",
                "Analysis": {"result_folder": f"results/riser-worked-configurations/{case_id}"},
                "riser_configuration_screen": settings}
    text = yaml.safe_dump(document, sort_keys=False)
    comments = {"submerged_weight_n_m": "computed: w = g*(rho_steel*A_steel + rho_content*A_bore - rho_seawater*A_displaced)",
                "max_top_tension_n": BASES["top_tension_n"],
                "min_bend_radius_m": BASES["bend_radius_m"],
                "min_hog_clearance_m": BASES["hog_clearance_m"],
                "max_static_utilisation": BASES["static_von_mises_utilisation"]}
    lines = []
    for line in text.splitlines():
        key = line.strip().split(":")[0]
        if key in comments:
            lines.append(" " * (len(line) - len(line.lstrip())) + "# " + comments[key])
        lines.append(line)
    return header + "\n".join(lines) + "\n"


def radius(row):
    """Use the same touchdown/sag/hog radius envelope as the screen."""
    return min([1 / row["touchdown_curvature_per_m"]]
               + [row[key] for key in ("sag_radius_m", "hog_radius_m") if row[key] is not None])


def criteria_for_row(settings, configuration, row):
    """Bind every row value to a limit, basis, signed margin and disposition."""
    limits = settings["constraints"]
    values = [
        ("top_tension_n", row["top_tension_n"], limits["max_top_tension_n"], "<=", "N"),
        ("bend_radius_m", radius(row), limits["min_bend_radius_m"], ">=", "m"),
        ("hog_clearance_m", row["hog_clearance_m"], limits["min_hog_clearance_m"], ">=", "m"),
        ("static_von_mises_utilisation", row["static_von_mises_utilisation"], limits["max_static_utilisation"], "<=", "1"),
        ("shape_closure", max(abs(row[k]) for k in ("vertical_closure_error_m", "horizontal_closure_error_m")), 1e-6, "<=", "m")]
    if settings["riser_type"] == "SLWR":
        values += [("net_buoyancy", configuration["buoyancy_factor"], 1., ">", "1"),
                   ("hog_above_sag", configuration["hog_fraction"] - configuration["sag_fraction"], 0., ">", "1")]
    checks = {}
    for name, computed, limit, relation, unit in values:
        margin = None if computed is None else (limit - computed if relation == "<=" else computed - limit)
        status = "not_applicable" if margin is None else (
            "pass" if margin > 0 or (margin == 0 and relation != ">") else "violation")
        checks[name] = {"criterion": {"name": name, "limit": limit, "basis": BASES[name],
                                      "relation": relation, "unit": unit},
                        "computed": computed, "margin": margin, "status": status,
                        "reason": "SCR has no hog bend" if computed is None else ""}
    return checks


def enrich_row(settings, configuration, row):
    """Keep exposed values, criteria and the conditional comparator scope."""
    row = dict(row)
    row["minimum_bend_radius_m"] = radius(row)
    row["top_tension_kn"] = row["top_tension_n"] / 1000
    row["horizontal_tension_kn"] = row["horizontal_tension_n"] / 1000
    row["criteria"] = criteria_for_row(settings, configuration, row)
    if settings["riser_type"] == "SCR":
        angle = configuration["hangoff_angle_deg"] if row["offset_m"] == 0 else row["top_angle_deg"]
        expected = scr_comparator(settings["submerged_weight_n_m"], settings["water_depth_m"], angle)
        row["touchdown_radius_m"] = 1 / row["touchdown_curvature_per_m"]
        scope = "selected input angle at zero offset; exposed top angle at other offsets"
    else:
        expected = slwr_comparator(settings["submerged_weight_n_m"], configuration["buoyancy_factor"],
                                  row["horizontal_tension_n"], row["buoyed_start_m"],
                                  row["buoyed_length_m"], row["suspended_length_m"])
        scope = "global vertical equilibrium and local radii conditional on exposed H and suspended lengths; H is not independently established"
    row["comparators"] = {name: comparison(value, row[name], scope) for name, value in expected.items()}
    row["comparators"]["static_von_mises_utilisation"] = stress_comparison(settings, configuration, row)
    return row


def select_result(settings):
    """Retain the first ranked candidate even when every candidate violates."""
    from digitalmodel.riser_configuration_screen.workflow import screen

    result = screen(settings)
    selected = result["ranked_candidates"][0]
    rows = [enrich_row(settings, selected["configuration"], row) for row in selected["offset_results"]]
    envelope = {}
    for name in rows[0]["criteria"] if rows else []:
        index = min(range(len(rows)), key=lambda i: (
            rows[i]["criteria"][name]["margin"] if rows[i]["criteria"][name]["margin"] is not None else math.inf))
        envelope[name] = {**rows[index]["criteria"][name], "offset_m": rows[index]["offset_m"]}
    governing = min(range(len(rows)), key=lambda i: min(
        c["margin"] / max(abs(c["criterion"]["limit"]), 1e-12)
        for c in rows[i]["criteria"].values() if c["margin"] is not None)) if rows else None
    return {"inputs": settings, "configuration": selected["configuration"], "rank": selected["rank"],
            "feasible": selected["feasible"], "grid_size": result["grid_size"],
            "feasible_count": sum(c["feasible"] for c in result["ranked_candidates"]),
            "input_sha256": result["input_sha256"], "limitations": result["limitations"],
            "selection_rule": result["selection_rule"], "screen_constraints": selected["constraints"],
            "curvature_range_per_m": selected["curvature_range_per_m"], "constraint_envelope": envelope,
            "offset_results": rows, "zero_offset_index": next((i for i, r in enumerate(rows) if r["offset_m"] == 0), None),
            "governing_offset_index": governing,
            "missing_evidence": "" if rows else "not established: no closed offset shapes; " + selected["constraints"]["shape_closure"]["reason"]}


def sensitivity_entry(result, step):
    """Use the candidate-wide load/utilisation maximum and radius minimum."""
    rows = result["offset_results"]
    metrics = {} if not rows else {
        "top_tension_kn": max(r["top_tension_kn"] for r in rows),
        "static_von_mises_utilisation": max(r["static_von_mises_utilisation"] for r in rows),
        "minimum_bend_radius_m": min(r["minimum_bend_radius_m"] for r in rows)}
    return {"wall_step": step, "wall_thickness_m": result["inputs"]["pipe"]["wall_thickness_m"],
            "submerged_weight_n_m": result["inputs"]["submerged_weight_n_m"],
            "max_top_tension_n": result["inputs"]["constraints"]["max_top_tension_n"],
            "configuration": result["configuration"], "feasible": result["feasible"],
            "feasible_count": result["feasible_count"], "constraint_envelope": result["constraint_envelope"],
            "stress_comparisons": [{**{key: row[key] for key in ("offset_m", "horizontal_tension_n", "top_tension_n",
                                                               "static_von_mises_utilisation")},
                                    "comparison": row["comparators"]["static_von_mises_utilisation"]} for row in rows],
            "metrics": round_values(metrics), "missing_evidence": result["missing_evidence"]}


def stress_evidence(cases):
    """Retain empirical tolerance evidence across every selected sensitivity row."""
    records = [{"case_id": case["case_id"], "wall_step": step["wall_step"], **row}
               for case in cases for step in case["sensitivity"] for row in step["stress_comparisons"]]
    largest = max(records, key=lambda row: abs(row["comparison"]["difference_percent"]))
    return {"relative_tolerance": STRESS_RELATIVE_TOLERANCE,
            "basis": "numerical-noise agreement across all base offsets and wall-step runs; no sampling allowance",
            "base_offset_rows": sum(len(case["offset_results"]) for case in cases),
            "sensitivity_runs": sum(len(case["sensitivity"]) for case in cases),
            "sensitivity_offset_rows": len(records),
            "maximum_absolute_difference_percent": abs(largest["comparison"]["difference_percent"]),
            "maximum_difference_row": {key: largest[key] for key in ("case_id", "wall_step", "offset_m")},
            "governing_critical_sections": sorted({row["comparison"]["governing_critical_section"] for row in records}),
            "not_established_rows": [{key: row[key] for key in ("case_id", "wall_step", "offset_m", "comparison")}
                                     for row in records if row["comparison"]["status"] != "pass"]}


def build_results():
    """Run all eighteen grids, keeping the base rows and sensitivity summaries."""
    cases = []
    for kind, depth, size in CASES:
        runs = [select_result(settings_for(kind, depth, size, t)) for t in SIZES[size][1]]
        base = runs[1]
        steps = [sensitivity_entry(r, label) for r, label in zip(runs, ("thinner", "base", "thicker"))]
        for step in steps:
            step["change_percent"] = {name: 100 * (value / steps[1]["metrics"][name] - 1)
                                      for name, value in step["metrics"].items() if name in steps[1]["metrics"]}
        cases.append({"case_id": f"{kind.lower()}-{depth}m-{size}in", **base, "sensitivity": steps})
    return {"tier": "SCREEN", "criteria_revision": "worked-config-1", "provisional": True,
            "data_basis": "generic assumed values for a public worked configuration; no project data",
            "sensitivity_basis": "generic nominal wall steps (assumed), not a vendor catalogue",
            "sensitivity_metrics": "rank-1 candidate envelope over all offsets: maximum top tension/utilisation, minimum radius; percentages use six-significant-figure metric values",
            "comparator_criterion": "relative difference <= 1e-6 before output rounding",
            "stress_comparator_evidence": stress_evidence(cases),
            "cases": cases}


def build_outputs():
    """Generate inputs and outputs in memory; package imports stay outside comparators."""
    # Import the sibling renderer for both CLI and importlib-based test loading.
    import importlib.util

    spec = importlib.util.spec_from_file_location("worked_report", HERE / "worked_configuration_report.py")
    report = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(report)
    data = build_results()
    outputs = {INPUTS / f"{case['case_id']}.yml": input_yaml(case["case_id"], case["inputs"])
               for case in data["cases"]}
    outputs[OUTPUT / "scr-slwr-results.json"] = json.dumps(round_values(data), indent=2, sort_keys=True, allow_nan=False) + "\n"
    outputs[OUTPUT / "scr-slwr-worked-configurations.md"] = report.render_report(data)
    for case in data["cases"]:
        outputs[OUTPUT / "figures" / f"{case['case_id']}.svg"] = report.render_svg(case)
    return outputs


def write_or_check(outputs, root=ROOT, check=False):
    """Check is read-only; writes are read back against the generated bytes."""
    differences = []
    for relative, content in outputs.items():
        path = root / relative
        expected = content.encode("utf-8")
        if check:
            if not path.is_file() or path.read_bytes() != expected:
                differences.append(relative.as_posix())
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(expected)
            if path.read_bytes() != expected:
                raise ValueError(f"saved artifact differs: {relative}")
    if differences:
        print("DIFFER: " + ", ".join(differences))
        return 1
    print(f"{'CHECK PASS' if check else 'WROTE'}: {len(outputs)} files")
    return 0


if __name__ == "__main__":
    if sys.argv[1:] not in ([], ["--check"]):
        raise SystemExit("usage: build_scr_slwr_worked_configurations.py [--check]")
    raise SystemExit(write_or_check(build_outputs(), check="--check" in sys.argv))
